scripts.claude:
#!/bin/sh
cd /Users/a/godspeed || exit 1
command -v claude >/dev/null 2>&1 || { echo "Claude Code isn't installed. Get it at https://claude.com/claude-code, then click Start again in godspeed."; exit 3; }
command -v node >/dev/null 2>&1 || { echo "godspeed needs Node.js. Install it from https://nodejs.org, then click Start again in godspeed."; exit 4; }
claude --version 2>/dev/null | node .godspeed/new-enough.mjs 2.1.330 || { echo "godspeed needs Claude Code 2.1.330 or newer. Update it (run: claude update), then click Start again in godspeed."; exit 6; }
if [ -n "$GODSPEED_RESUME" ]; then exec claude --settings .godspeed/claude-settings.json --strict-mcp-config --mcp-config .mcp.json --disallowedTools Agent Skill --autocompact 150000 --resume "$GODSPEED_RESUME"; fi
exec claude --settings .godspeed/claude-settings.json --strict-mcp-config --mcp-config .mcp.json --disallowedTools Agent Skill --autocompact 150000

