scripts.claude:
#!/bin/sh
cd / || exit 1
command -v ./bin/claude-wrap.sh >/dev/null 2>&1 || { echo "godspeed couldn't find ./bin/claude-wrap.sh. Check the command under Change command in godspeed."; exit 3; }
command -v node >/dev/null 2>&1 || { echo "godspeed needs Node.js. Install it from https://nodejs.org, then click Start again in godspeed."; exit 4; }
if [ -n "$GODSPEED_RESUME" ]; then ./bin/claude-wrap.sh --x 'a b' $HOME `id` "q" & | ; %PATH% --settings .godspeed/claude-settings.json --strict-mcp-config --mcp-config .mcp.json --disallowedTools Agent Skill --autocompact 150000 --resume "$GODSPEED_RESUME"; exit $?; fi
./bin/claude-wrap.sh --x 'a b' $HOME `id` "q" & | ; %PATH% --settings .godspeed/claude-settings.json --strict-mcp-config --mcp-config .mcp.json --disallowedTools Agent Skill --autocompact 150000

